bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec -w /opt/videobot "$cid" node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import {buildFreeAlbumRequest} from '/opt/videobot/src/telegram/freeAlbum.mjs';
import {buildPaidMediaRequest} from '/opt/videobot/src/telegram/paidMedia.mjs';
const f=buildFreeAlbumRequest({chatId:-1002373696859,messageThreadId:1613,thumbnailFileId:'testPhoto_123',sampleFileId:'testSample_456'});
assert.equal(f.media.length,2);
assert.equal(f.media[0].type,'photo');
assert.equal(f.media[1].type,'video');
assert.equal(f.media[0].has_spoiler,true);
assert.equal(f.media[1].has_spoiler,true);
const p=buildPaidMediaRequest({chatId:-1002373696859,messageThreadId:1613,mediaFileId:'testPaid_789',priceStars:10,payload:'test_123:1'});
assert.equal(p.star_count,10);
assert.equal(p.media.length,1);
assert.equal(p.media[0].type,'video');
assert.notEqual(p.media[0].media,f.media[1].media);
console.log('LIVE_FREE_ALBUM_SPOILERS_AND_PAID_REQUEST_SCHEMA=PASS');
JS
